const $ = (s,root=document)=>root.querySelector(s);
const $$ = (s,root=document)=>[...root.querySelectorAll(s)];
const names={toast:'戴蓝色眼镜的超市小观察员',picnic:'客厅里拍手的小朋友',shop:'骑木雕牛的小骑手',music:'面对镜头开怀大笑'};
let motion=!matchMedia('(prefers-reduced-motion: reduce)').matches,editing=false,uploadTarget=null,noticeTimer;
const original=new Map(),replacements=new Map(),playing=new Set();
function notice(message){$('#toast').textContent=tr(message);$('#toast').classList.add('visible');clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3500)}
function readStorage(key,fallback){try{return JSON.parse(localStorage.getItem('family-oct16:'+key))??fallback}catch{return fallback}}
function writeStorage(key,value){try{localStorage.setItem('family-oct16:'+key,JSON.stringify(value));return true}catch{return false}}
let copy=readStorage('tt-copy-'+window.TT_LOCALE,window.TT_LOCALE==='zh'?readStorage('tt-copy',{}):{});
const framing=readStorage('tt-framing',{});
$$('[data-copy]').forEach(el=>{original.set(el.dataset.copy,el.innerHTML);if(typeof copy[el.dataset.copy]==='string')el.textContent=copy[el.dataset.copy];el.addEventListener('input',()=>{copy[el.dataset.copy]=el.innerText;if(!writeStorage('tt-copy-'+window.TT_LOCALE,copy))notice('当前浏览器无法保存文字，请保持页面打开。')});el.addEventListener('paste',event=>{event.preventDefault();const text=event.clipboardData.getData('text/plain');const selection=getSelection();if(!selection.rangeCount)return;const range=selection.getRangeAt(0);range.deleteContents();const node=document.createTextNode(text);range.insertNode(node);range.setStartAfter(node);range.collapse(true);selection.removeAllRanges();selection.addRange(range);el.dispatchEvent(new Event('input'))})});
const mediaDB=new Promise(resolve=>{if(!window.indexedDB)return resolve(null);const req=indexedDB.open('toddler-times-family-oct16',1);req.onupgradeneeded=()=>req.result.createObjectStore('files');req.onsuccess=()=>resolve(req.result);req.onerror=()=>resolve(null)});
async function saveMedia(id,file){const db=await mediaDB;if(!db)return false;return new Promise(resolve=>{try{const tx=db.transaction('files','readwrite');tx.objectStore('files').put(file,id);tx.oncomplete=()=>resolve(true);tx.onerror=()=>resolve(false);tx.onabort=()=>resolve(false)}catch{resolve(false)}})}
async function clearMedia(){const db=await mediaDB;if(!db)return;return new Promise(resolve=>{const tx=db.transaction('files','readwrite');tx.objectStore('files').clear();tx.oncomplete=resolve;tx.onerror=resolve})}
function stop(box){playing.delete(box);const video=$('video',box);if(video)video.pause();box.classList.remove('is-playing');$('.media-hit',box)?.setAttribute('aria-pressed','false')}
async function start(box){if(!motion||editing)return;$$('.media').forEach(other=>{if(other!==box)stop(other)});const video=$('video',box);box.classList.add('is-playing');playing.add(box);$('.media-hit',box).setAttribute('aria-pressed','true');if(video){try{await video.play()}catch{stop(box);notice('视频暂时无法播放，请重试或替换素材。')}}}
function toggle(box){if(editing)return;if(!motion){motion=true;updateMotion()}box.classList.contains('is-playing')?stop(box):start(box)}
function formatDuration(seconds){const total=Math.max(1,Math.ceil(seconds));return `${Math.floor(total/60)}:${String(total%60).padStart(2,'0')}`}
function renderMedia(box){
 const id=box.dataset.media;stop(box);box.classList.remove('load-error');const replacement=replacements.get(id);const isImage=replacement?.file.type.startsWith('image/');box.replaceChildren();box.classList.remove('frame-adjusting');
 const focus=framing[id]||{x:50,y:({toast:28,picnic:12,shop:15,music:0})[id]};box.style.setProperty('--focus-x',focus.x+'%');box.style.setProperty('--focus-y',focus.y+'%');
 const visual=document.createElement(isImage?'img':'video');
 visual.src=replacement?.url||window.TT_ASSETS?.[id]?.video||`assets/${id}.mp4`;
 if(isImage)visual.alt=names[id];else{visual.muted=true;visual.loop=true;visual.playsInline=true;visual.preload='metadata';if(!replacement)visual.poster=window.TT_ASSETS?.[id]?.poster||`assets/${id}.jpg`;visual.addEventListener('error',()=>{stop(box);box.classList.add('load-error');$('.media-hit',box)?.setAttribute('aria-label','素材加载失败，请替换影像')})}
 box.append(visual);
 const overlay=document.createElement('div');
 overlay.innerHTML=`<button class="media-hit" aria-label="播放或暂停：${names[id]}" aria-pressed="false"></button>${isImage?'':'<span class="media-duration" hidden></span>'}<div class="media-bottom"><button class="expand" aria-label="放大查看：${names[id]}"><svg viewBox="0 0 24 24" width="17" height="17" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M14 5h5v5M19 5l-6 6M10 19H5v-5M5 19l6-6"/></svg></button></div><button class="replace">＋ 替换影像</button><button class="reframe" aria-expanded="false">调整构图</button><div class="framing-panel"><label>左右<input type="range" min="0" max="100" value="${focus.x}" data-axis="x" aria-label="左右取景位置"></label><label>上下<input type="range" min="0" max="100" value="${focus.y}" data-axis="y" aria-label="上下取景位置"></label><p>保留人物，裁去边缘 · 自动保存</p></div>`;
 while(overlay.firstChild)box.append(overlay.firstChild);
 if(!isImage){const updateDuration=()=>{const label=$('.media-duration',box);if(Number.isFinite(visual.duration)&&visual.duration>0){label.textContent=formatDuration(visual.duration);label.setAttribute('aria-label',`视频时长 ${label.textContent}`);label.hidden=false}};visual.addEventListener('loadedmetadata',updateDuration);visual.addEventListener('durationchange',updateDuration);updateDuration()}
 $('.reframe',box).onclick=()=>{const open=box.classList.toggle('frame-adjusting');$('.reframe',box).setAttribute('aria-expanded',String(open));$('.reframe',box).textContent=open?'完成构图':'调整构图'};
 $$('.framing-panel input',box).forEach(input=>input.oninput=()=>{const axis=input.dataset.axis;focus[axis]=Number(input.value);box.style.setProperty('--focus-'+axis,focus[axis]+'%');framing[id]={...focus};writeStorage('tt-framing',framing)});
 $('.media-hit',box).onclick=()=>toggle(box);$('.expand',box).onclick=()=>openReader(box);$('.replace',box).onclick=()=>{uploadTarget=box;$('#file-input').click()};box.onpointerenter=e=>{if(e.pointerType==='mouse')start(box)};box.onpointerleave=e=>{if(e.pointerType==='mouse')stop(box)}
}
$$('.media').forEach(renderMedia);
mediaDB.then(db=>{if(!db)return;const req=db.transaction('files').objectStore('files').openCursor();req.onsuccess=()=>{const cursor=req.result;if(!cursor)return;const box=$(`[data-media="${cursor.key}"]`);if(box&&cursor.value instanceof Blob&&!replacements.has(cursor.key)){replacements.set(cursor.key,{file:cursor.value,url:URL.createObjectURL(cursor.value)});renderMedia(box)}cursor.continue()}});
const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(!entry.isIntersecting)stop(entry.target)}),{threshold:.1});$$('.media').forEach(box=>observer.observe(box));document.addEventListener('visibilitychange',()=>{if(document.hidden){$$('.media').forEach(stop);$('#reader video')?.pause()}});
function updateMotion(){document.body.classList.toggle('motion-off',!motion);$('#motion').setAttribute('aria-pressed',String(motion));$('#motion span:last-child').textContent=motion?'动态照片已开启':'动态照片已暂停';if(!motion)$$('.media').forEach(stop)}
$('#motion').onclick=()=>{motion=!motion;updateMotion();notice(motion?'动态照片已开启':'全部动态照片已暂停')};updateMotion();
function openReader(box){$$('.media').forEach(stop);const story=box.closest('.story');$('#reader h2').textContent=$('h2',story).innerText;$('#reader .reader-text p').textContent=$('.prose p',story).textContent;const media=$('video,img',box).cloneNode(true);if(media.tagName==='VIDEO'){media.controls=true;media.muted=true;media.loop=true;media.preload='auto'}$('#reader-media').replaceChildren(media);$('#reader').showModal();document.body.style.overflow='hidden';if(media.tagName==='VIDEO'&&motion)media.play().catch(()=>{});}
$$('dialog .close').forEach(button=>button.onclick=()=>button.closest('dialog').close());$$('dialog').forEach(dialog=>{dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});dialog.addEventListener('close',()=>{document.body.style.overflow='';if(dialog.id==='reader'){$('video',dialog)?.pause();$('#reader-media').replaceChildren()}})});
$('#settings').onclick=()=>$('#preferences').showModal();const prefs=readStorage('tt-prefs',{size:'normal',tone:'warm'});function applyPrefs(){document.body.classList.toggle('large',prefs.size==='large');document.body.classList.toggle('white',prefs.tone==='white');$('#text-size').value=prefs.size;$('#paper-tone').value=prefs.tone;writeStorage('tt-prefs',prefs)}$('#text-size').onchange=e=>{prefs.size=e.target.value;applyPrefs()};$('#paper-tone').onchange=e=>{prefs.tone=e.target.value;applyPrefs()};applyPrefs();
function setEditing(value){editing=value;document.body.classList.toggle('editing',value);$('.edit-dock').hidden=!value;$('#edit').textContent=value?'正在编辑':'编辑本期';$('#edit').setAttribute('aria-pressed',String(value));$$('[data-copy]').forEach(el=>{el.contentEditable=value?'true':'false';el.spellcheck=false});$$('.media').forEach(stop)}
$('#edit').onclick=()=>setEditing(!editing);$('#replace-help').onclick=()=>{setEditing(true);$('#food').scrollIntoView({behavior:'smooth'});notice('点击照片右上角的「替换影像」，选择照片或视频。')};$('#done').onclick=()=>{setEditing(false);notice('本期修改已保存在当前浏览器')};
$('#file-input').onchange=async e=>{const file=e.target.files[0];const box=uploadTarget;e.target.value='';if(!file||!box)return;if(!/^(image|video)\//.test(file.type)){notice('请选择照片或视频文件。');return}if(file.size>150*1024*1024){notice('请选择小于 150 MB 的文件。');return}const id=box.dataset.media;const old=replacements.get(id);if(old)URL.revokeObjectURL(old.url);replacements.set(id,{file,url:URL.createObjectURL(file)});renderMedia(box);const saved=await saveMedia(id,file);notice(saved?'影像已替换，并保存在当前浏览器。':'影像已替换，但浏览器存储不可用；刷新后需重新选择。')};
$('#reset').onclick=async()=>{if(!confirm(tr('恢复本期示例？你修改的文字和替换的素材将被清除。')))return;await clearMedia();Object.keys(framing).forEach(key=>delete framing[key]);writeStorage('tt-framing',{});replacements.forEach(value=>URL.revokeObjectURL(value.url));replacements.clear();Object.keys(copy).forEach(key=>delete copy[key]);writeStorage('tt-copy-'+window.TT_LOCALE,{});$$('[data-copy]').forEach(el=>el.innerHTML=original.get(el.dataset.copy));$$('.media').forEach(renderMedia);notice('已恢复本期示例。')};
$$('.sections a').forEach(a=>a.onclick=()=>{$$('.sections a').forEach(link=>link.classList.toggle('active',link===a))});

$$('[data-language]').forEach(button=>button.onclick=()=>{
 const next=button.dataset.language;if(next===window.TT_LOCALE)return;
 $$('.media').forEach(stop);$$('dialog[open]').forEach(d=>d.close());
 window.TT_LOCALE=next;try{localStorage.setItem('family-oct16:language',next)}catch{}
 copy=readStorage('tt-copy-'+next,next==='zh'?readStorage('tt-copy',{}):{});
 $$('[data-copy]').forEach(el=>{const key=el.dataset.copy;const html=window.TT_defaultCopy(key);original.set(key,html);if(typeof copy[key]==='string')el.textContent=copy[key];else el.innerHTML=html});
 $('#toast').classList.remove('visible');window.TT_languageChrome();updateMotion();setEditing(editing);
});
window.TT_localize();
